select car_makers.Id, car_makers.Maker from car_makers join model_list on car_makers.Id = model_list.Maker join car_names on model_list.Model = car_names.Model join cars_data on car_names.MakeId = cars_data.Id where cars_data.Horsepower > (select min(Horsepower) from cars_data) and cars_data.Cylinders < 4	car_1
select car_makers.Maker, cars_data.Year from cars_data join car_names on cars_data.Id = car_names.MakeId join model_list on car_names.Model = model_list.Model join car_makers on model_list.Maker = car_makers.Id where cars_data.Year = (select min(Year) from cars_data)	car_1
